-- Curated expanded-dex habitats for Kanto and Johto.
--
-- This is deliberately a substitution layer, not a ROM-table rewrite: the
-- original encounter decides whether a battle occurs and supplies its level.
-- We only replace the species on a minority of successful rolls. That keeps
-- encounter rates and progression intact on Red/Blue/Yellow, Gold/Silver and
-- map conversions while giving registered Gen 2/3 species stable homes.

local H = {}

local function words(s)
  local out = {}
  for id in tostring(s or ""):gmatch("%S+") do out[#out + 1] = id end
  return out
end

